extract_form_inputs.code:
(params) => {
  const root = params && params.formSelector ? document.querySelector(params.formSelector) : document;
  if (!root) return { error: 'Form element not found' };
  const inputs = Array.from(root.querySelectorAll('input, select, textarea'));
  return inputs.map(el => ({
    tagName: el.tagName.toLowerCase(),
    name: el.getAttribute('name') || '',
    id: el.id || '',
    type: el.getAttribute('type') || '',
    value: (el as any).value || ''
  }));
}

extract_page_metadata.code:
() => {
  const title = document.title;
  const metaDesc = document.querySelector('meta[name="description"]');
  const canonical = document.querySelector('link[rel="canonical"]');
  return {
    title,
    description: metaDesc ? metaDesc.getAttribute('content') : null,
    canonical: canonical ? canonical.getAttribute('href') : null,
    url: window.location.href
  };
}

get_element_text.code:
(params) => {
  if (!params || !params.selector) return { error: 'selector is required' };
  const el = document.querySelector(params.selector);
  if (!el) return { error: 'Element not found' };
  return {
    textContent: el.textContent ? el.textContent.trim() : '',
    innerText: (el as HTMLElement).innerText || ''
  };
}
